  orgId: OrgId,
  recipientId: UserId,
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(notifications)
    .where(
      and(
        orgPredicate(notifications.orgId, orgId),
        eq(notifications.recipientId, recipientId),
        isNull(notifications.readAt),
      ),
    )
    .get();
  return row?.value ?? 0;
}

