/**
 * A removed member is archived, never deleted, and no read ever surfaces one:
 * the scope is fixed here rather than threaded through every call site.
 */
const LIVE_MEMBERS: { readonly includeArchived?: boolean } = {};

function liveMemberPredicate() {
  return shouldFilterArchived(LIVE_MEMBERS) ? isNull(members.archivedAt) : undefined;
}

export async function findMember(
  orgId: OrgId,
  userId: UserId,
): Promise<Member | null> {
  const row = getDb()
    .select()
    .from(members)
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        eq(members.userId, userId),
        liveMemberPredicate(),
      ),
    )
    .get();
  return row ? toMember(row) : null;
}

export async function findMemberById(
  orgId: OrgId,
  memberId: MemberId,
): Promise<Member | null> {
  const row = getDb()
    .select()
    .from(members)
    .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
    .get();
  return row ? toMember(row) : null;
}

/** Cursor-paged member list joined with the user record the UI renders. */
export async function listMembers(
  input: ListMembersInput,
): Promise<Page<MemberWithUser>> {
  const db = getDb();
  const sort = { sortColumn: members.createdAt, idColumn: members.id };

  const filters = compact(
    orgPredicate(members.orgId, input.orgId),
    liveMemberPredicate(),
    input.role === undefined ? undefined : eq(members.role, input.role),
    input.status === undefined ? undefined : eq(members.status, input.status),
    input.query === undefined
      ? undefined
      : or(
          like(users.name, `%${input.query}%`),
          like(users.email, `%${input.query}%`),
        ),
  );

  const total = db
    .select({ value: count() })
    .from(members)
    .innerJoin(users, eq(users.id, members.userId))
    .where(and(...filters))
    .get();

  const rows = db
    .select({ member: members, user: users })
    .from(members)
    .innerJoin(users, eq(users.id, members.userId))
    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
    .orderBy(desc(members.createdAt), desc(members.id))
    .limit(probeLimit(input.limit))
    .all();

  return toPage(
    rows,
    input.limit,
    total?.value ?? 0,
    (row) => ({ ...toMember(row.member), user: toUser(row.user) }),
    (row) => ({ id: row.member.id, sortValue: row.member.createdAt }),
  );
}

/** The seat count every plan check compares against. */
export async function countActiveMembers(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(members)
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        eq(members.status, "active"),
        liveMemberPredicate(),
      ),
    )
    .get();
  return row?.value ?? 0;
}

export async function insertMember(
  orgId: OrgId,
  userId: UserId,
  role: Role,
  invitedBy: UserId | null,
): Promise<Member> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(members)
    .values({
      id: newId(),
      orgId,
      userId,
      role,
      status: "active",
      invitedBy,
      joinedAt: stamp,
      lastSeenAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toMember(row);
}

export async function updateMemberRole(
  orgId: OrgId,
  memberId: MemberId,
  role: Role,
): Promise<Member> {
  const row = getDb()
    .update(members)
    .set({ role, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
    .returning()
    .get();

  if (!row) throw new Error(`Member ${memberId} not found in org ${orgId}`);
  return toMember(row);
}

/** Removal is a soft delete so the audit log keeps pointing at a real row. */
export async function archiveMember(
  orgId: OrgId,
  memberId: MemberId,
): Promise<Member> {
  const row = getDb()
    .update(members)
    .set({ ...archivePatch(), status: "suspended" })
    .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
    .returning()
    .get();

  if (!row) throw new Error(`Member ${memberId} not found in org ${orgId}`);
  return toMember(row);
}

export async function touchLastSeen(
  orgId: OrgId,
  userId: UserId,
  at: IsoTimestamp,
): Promise<void> {
  getDb()
    .update(members)
    .set({ lastSeenAt: at })
    .where(and(orgPredicate(members.orgId, orgId), eq(members.userId, userId)))
    .run();
}

/**
 * In-memory SQLite fixture: migrate, seed a tenant pair, reset between tests.
 *
 * Repository and service suites call `setupTestDb()` once, `resetTestDb()` in
 * `beforeEach` and `seedTwoTenants()` when they need two organizations to
 * prove a query is org-scoped. The database is `:memory:`, so nothing here
 * touches the developer's `data/taskflow.db`.
 */
// Aliased on import: the contract calls it `useInMemoryDb`, which the
// react-hooks lint rule would otherwise mistake for a React hook here.
import { getDb, useInMemoryDb as attachInMemoryDb } from "@/server/db";
import { runMigrations } from "@/server/db/migrate";
import { organizations } from "@/server/db/schema/organizations";
import { users } from "@/server/db/schema/users";
import type { Organization } from "@/types/organization";
import { makeOrganization, ORG_A, ORG_B } from "./factories";

let migrated = false;

/** Points the singleton client at an in-memory database and migrates it. */
export async function setupTestDb(): Promise<void> {
  attachInMemoryDb();
  await runMigrations(":memory:");
  migrated = true;
}

/** Truncates every table, keeping the schema — cheaper than re-migrating. */
export async function resetTestDb(): Promise<void> {
  if (!migrated) await setupTestDb();

  const db = getDb();
  const tables = db.$client
    .prepare(
      "SELECT name FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%' AND name NOT LIKE '__drizzle%'",
    )
    .all() as readonly { name: string }[];

  db.$client.pragma("foreign_keys = OFF");
  for (const table of tables) {
    db.$client.prepare(`DELETE FROM "${table.name}"`).run();
  }
  db.$client.pragma("foreign_keys = ON");
}

/**
 * Inserts two organizations owned by two different users. Every "does this
 * query filter by orgId?" test seeds through here so the negative case is a
 * real row in a real other tenant, not an absence.
 */
export async function seedTwoTenants(): Promise<{
  orgA: Organization;
  orgB: Organization;
}> {
  const db = getDb();

  const orgA = makeOrganization({ id: ORG_A, name: "Acme", slug: "acme" });
  const orgB = makeOrganization({
    id: ORG_B,
    name: "Globex",
    slug: "globex",
    ownerId: orgA.ownerId,
  });

  await db
    .insert(users)
    .values({
      id: orgA.ownerId,
      email: "owner@example.com",
      name: "Test Owner",
      passwordHash: "scrypt:00:00",
      timezone: "UTC",
      createdAt: orgA.createdAt,
      updatedAt: orgA.updatedAt,
    })
    .onConflictDoNothing();

  for (const org of [orgA, orgB]) {
    await db.insert(organizations).values({
      id: org.id,
      name: org.name,
      slug: org.slug,
      ownerId: org.ownerId,
      plan: org.plan,
      logoUrl: org.logoUrl,
      trialEndsAt: org.trialEndsAt,
      // `OrganizationSettings` is flattened across columns on this table.
      defaultIssueStatus: org.settings.defaultIssueStatus,
      allowPublicProjects: org.settings.allowPublicProjects,
      requireTwoFactor: org.settings.requireTwoFactor,
      digestHourUtc: org.settings.digestHourUtc,
      enabledFlagOverrides: JSON.stringify(org.settings.enabledFlagOverrides),
      archivedAt: org.archivedAt,
      createdAt: org.createdAt,
      updatedAt: org.updatedAt,
    });
  }

  return { orgA, orgB };
}
