    memberCount: await memberRepo.countActiveMembers(orgId),
    projectCount: await projectRepo.countProjects(orgId),
  };
}

/** Offer the recorded workspace ownership to another active member. */
export async function initiateOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
  toUserId: UserId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );
  assertRecordedOwner(actor, org.ownerId);

  if (toUserId === actor.userId) {
    throw new OwnershipHandoverError("self");
  }

  const target = await memberRepo.findMember(orgId, toUserId);
  if (!target || target.status !== "active" || target.archivedAt !== null) {
    throw new NotFoundError("Member", toUserId);
  }

  const handover = await ownershipHandoverRepo.createPending(
    orgId,
    actor.userId,
    toUserId,
    toIsoTimestamp(new Date()),
  );
  if (!handover) throw new OwnershipHandoverError("pending_exists");

  await notify(orgId, "ownership_handover", [toUserId], {
    title: "Workspace ownership offered",
    body: `${actor.userId} invited you to take ownership of this workspace`,
    href: "/settings/members",
    actorId: actor.userId,
  });

  return handover;
}

/** Accept the current offer and atomically take the recorded owner role. */
export async function acceptOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<Organization> {
  assertOrgScope(actor, orgId);
  const result = await ownershipHandoverRepo.acceptPending(
    orgId,
    actor.userId,
    toIsoTimestamp(new Date()),
  );
  if (result.kind === "refused") {
    throw new OwnershipHandoverError(result.reason);
  }

  for (const change of result.roleChanges) {
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: change.memberId,
      from: change.from,
      to: change.to,
    });
  }

  await emit("organization.ownership_transferred", {
    ...actorEnvelope(actor),
    fromUserId: result.handover.fromUserId,
    toUserId: result.handover.toUserId,
  });

  return result.organization;
}

/** Decline the current offer. Only the named recipient can act on it. */
export async function declineOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  const result = await ownershipHandoverRepo.declinePending(
    orgId,
    actor.userId,
    toIsoTimestamp(new Date()),
  );
  if (result.kind === "refused") {
    throw new OwnershipHandoverError(result.reason);
  }
  return result.handover;
}

/** Withdraw the current offer as its recorded owner. */
export async function cancelOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );
  assertRecordedOwner(actor, org.ownerId);

  const handover = await ownershipHandoverRepo.cancelPending(
    orgId,
    toIsoTimestamp(new Date()),
  );
  if (!handover) throw new OwnershipHandoverError("nothing_pending");
  return handover;
}

/** Any active workspace member can check whether an offer is open. */
export async function getPendingOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));
  return ownershipHandoverRepo.findPending(orgId, toIsoTimestamp(new Date()));
}

