import { and, eq, lte } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, members, organizations, ownershipHandovers } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { toMember, toOrganization, toOwnershipHandover } from "./_mappers";
import type { MemberId, OrgId, UserId } from "@/types/common";
import type { OwnershipHandover } from "@/types/organization";
import type { Role } from "@/types/member";

const HANDOVER_WINDOW_MS = 7 * 24 * 60 * 60 * 1000;

export type HandoverRefusal = "nothing_pending" | "expired";

export type AcceptHandoverResult =
  | { readonly kind: "refused"; readonly reason: HandoverRefusal }
  | {
      readonly kind: "accepted";
      readonly handover: OwnershipHandover;
      readonly organization: ReturnType<typeof toOrganization>;
      readonly roleChanges: readonly {
        readonly memberId: MemberId;
        readonly from: Role;
        readonly to: Role;
      }[];
    };

type ResolveHandoverResult =
  | { readonly kind: "refused"; readonly reason: HandoverRefusal }
  | { readonly kind: "resolved"; readonly handover: OwnershipHandover };

/** Create an offer if there is no unexpired one already open. */
export async function createPending(
  orgId: OrgId,
  fromUserId: UserId,
  toUserId: UserId,
  now: ReturnType<typeof toIsoTimestamp>,
): Promise<OwnershipHandover | null> {
  const db = getDb();
  return db.transaction((tx) => {
    expireLapsed(tx, orgId, now);
    const existing = tx
      .select()
      .from(ownershipHandovers)
      .where(
        and(
          eq(ownershipHandovers.orgId, orgId),
          eq(ownershipHandovers.status, "pending"),
        ),
      )
      .get();
    if (existing) return null;

    const createdAt = now;
    const expiresAt = toIsoTimestamp(
      new Date(new Date(createdAt).getTime() + HANDOVER_WINDOW_MS),
    );
    const row = tx
      .insert(ownershipHandovers)
      .values({
        id: newId(),
        orgId,
        fromUserId,
        toUserId,
        status: "pending",
        expiresAt,
        resolvedAt: null,
        createdAt,
        updatedAt: createdAt,
      })
      .returning()
      .get();
    return toOwnershipHandover(row);
  });
}

/** Return the live offer; a boundary-time expiry is no longer pending. */
export async function findPending(
  orgId: OrgId,
  now: ReturnType<typeof toIsoTimestamp>,
): Promise<OwnershipHandover | null> {
  const db = getDb();
  return db.transaction((tx) => {
    expireLapsed(tx, orgId, now);
    const row = tx
      .select()
      .from(ownershipHandovers)
      .where(
        and(
          eq(ownershipHandovers.orgId, orgId),
          eq(ownershipHandovers.status, "pending"),
        ),
      )
      .get();
    return row ? toOwnershipHandover(row) : null;
  });
}

/** Decline only when the actor is the named recipient and the offer is live. */
export async function declinePending(
  orgId: OrgId,
  actorUserId: UserId,
  now: ReturnType<typeof toIsoTimestamp>,
): Promise<ResolveHandoverResult> {
  const db = getDb();
  return db.transaction((tx) => {
    const row = pendingRow(tx, orgId);
    if (!row) return { kind: "refused", reason: "nothing_pending" };

    if (row.expiresAt <= now) {
      resolveAsExpired(tx, row.id, row.expiresAt, now);
      return {
        kind: "refused",
        reason: row.toUserId === actorUserId ? "expired" : "nothing_pending",
      };
    }
    if (row.toUserId !== actorUserId) {
      return { kind: "refused", reason: "nothing_pending" };
    }

    const updated = tx
      .update(ownershipHandovers)
      .set({ status: "declined", resolvedAt: now, updatedAt: now })
      .where(eq(ownershipHandovers.id, row.id))
      .returning()
      .get();
    return { kind: "resolved", handover: toOwnershipHandover(updated) };
  });
}

/** Withdraw the current live offer. Callers must first check recorded ownership. */
export async function cancelPending(
  orgId: OrgId,
  now: ReturnType<typeof toIsoTimestamp>,
): Promise<OwnershipHandover | null> {
  const db = getDb();
  return db.transaction((tx) => {
    expireLapsed(tx, orgId, now);
    const row = pendingRow(tx, orgId);
    if (!row) return null;

    const updated = tx
      .update(ownershipHandovers)
      .set({ status: "canceled", resolvedAt: now, updatedAt: now })
      .where(eq(ownershipHandovers.id, row.id))
      .returning()
      .get();
    return toOwnershipHandover(updated);
  });
}

/**
 * Resolve the offer and exchange roles in one SQLite transaction. The target
 * is promoted before the old owner is demoted so a workspace always has an
 * owner, including when the old owner was its only owner-role member.
 */
export async function acceptPending(
  orgId: OrgId,
  actorUserId: UserId,
  now: ReturnType<typeof toIsoTimestamp>,
): Promise<AcceptHandoverResult> {
  const db = getDb();
  return db.transaction((tx) => {
    const row = pendingRow(tx, orgId);
    if (!row) return { kind: "refused", reason: "nothing_pending" };

    if (row.expiresAt <= now) {
      resolveAsExpired(tx, row.id, row.expiresAt, now);
      return {
        kind: "refused",
        reason: row.toUserId === actorUserId ? "expired" : "nothing_pending",
      };
    }
    if (row.toUserId !== actorUserId) {
      return { kind: "refused", reason: "nothing_pending" };
    }

    const organizationRow = tx
      .select()
      .from(organizations)
      .where(eq(organizations.id, orgId))
      .get();
    const targetRow = tx
      .select()
      .from(members)
      .where(
        and(
          eq(members.orgId, orgId),
          eq(members.userId, row.toUserId),
          eq(members.status, "active"),
        ),
      )
      .get();
    const previousRow = tx
      .select()
      .from(members)
      .where(
        and(
          eq(members.orgId, orgId),
          eq(members.userId, row.fromUserId),
          eq(members.status, "active"),
        ),
      )
      .get();

    if (
      !organizationRow ||
      organizationRow.ownerId !== row.fromUserId ||
      !targetRow ||
      targetRow.archivedAt !== null ||
      !previousRow ||
      previousRow.archivedAt !== null
    ) {
      tx.update(ownershipHandovers)
        .set({ status: "canceled", resolvedAt: now, updatedAt: now })
        .where(eq(ownershipHandovers.id, row.id))
        .run();
      return { kind: "refused", reason: "nothing_pending" };
    }

    const roleChanges: { memberId: MemberId; from: Role; to: Role }[] = [];
    if (targetRow.role !== "owner") {
      tx.update(members)
        .set({ role: "owner", updatedAt: now })
        .where(eq(members.id, targetRow.id))
        .run();
      roleChanges.push({
        memberId: targetRow.id as MemberId,
        from: targetRow.role,
        to: "owner",
      });
    }

    const updatedOrganization = tx
      .update(organizations)
      .set({ ownerId: row.toUserId, updatedAt: now })
      .where(eq(organizations.id, orgId))
      .returning()
      .get();

    if (previousRow.role === "owner") {
      tx.update(members)
        .set({ role: "admin", updatedAt: now })
        .where(eq(members.id, previousRow.id))
        .run();
      roleChanges.push({
        memberId: previousRow.id as MemberId,
        from: "owner",
        to: "admin",
      });
    }

    const resolvedRow = tx
      .update(ownershipHandovers)
      .set({ status: "accepted", resolvedAt: now, updatedAt: now })
      .where(eq(ownershipHandovers.id, row.id))
      .returning()
      .get();

    return {
      kind: "accepted",
      handover: toOwnershipHandover(resolvedRow),
      organization: toOrganization(updatedOrganization),
      roleChanges,
    };
  });
}

/** Cancel open offers if either participant leaves via member removal. */
export async function cancelForMember(
  orgId: OrgId,
  userId: UserId,
  now: ReturnType<typeof toIsoTimestamp>,
): Promise<void> {
  const db = getDb();
  db.transaction((tx) => {
    expireLapsed(tx, orgId, now);
    const rows = tx
      .select()
      .from(ownershipHandovers)
      .where(
        and(
          eq(ownershipHandovers.orgId, orgId),
          eq(ownershipHandovers.status, "pending"),
        ),
      )
      .all();
    for (const row of rows) {
      if (row.fromUserId !== userId && row.toUserId !== userId) continue;
      tx.update(ownershipHandovers)
        .set({ status: "canceled", resolvedAt: now, updatedAt: now })
        .where(eq(ownershipHandovers.id, row.id))
        .run();
    }
  });
}

function pendingRow(tx: Parameters<Parameters<ReturnType<typeof getDb>["transaction"]>[0]>[0], orgId: OrgId) {
  return tx
    .select()
    .from(ownershipHandovers)
    .where(
      and(
        eq(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
      ),
    )
    .get();
}

function expireLapsed(
  tx: Parameters<Parameters<ReturnType<typeof getDb>["transaction"]>[0]>[0],
  orgId: OrgId,
  now: ReturnType<typeof toIsoTimestamp>,
): void {
  const rows = tx
    .select()
    .from(ownershipHandovers)
    .where(
      and(
        eq(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
        lte(ownershipHandovers.expiresAt, now),
      ),
    )
    .all();
  for (const row of rows) resolveAsExpired(tx, row.id, row.expiresAt, now);
}

function resolveAsExpired(
  tx: Parameters<Parameters<ReturnType<typeof getDb>["transaction"]>[0]>[0],
  id: string,
  expiresAt: string,
  now: ReturnType<typeof toIsoTimestamp>,
): void {
  tx.update(ownershipHandovers)
    .set({ status: "expired", resolvedAt: expiresAt, updatedAt: now })
    .where(eq(ownershipHandovers.id, id))
    .run();
}

